pub(crate) fn whitelist_matches(
    whitelist: &Option<Map<ContractAddress, ()>>,
    addr: &ContractAddress,
) -> bool {
    match whitelist {
        Some(wl) => wl.contains_key(addr),
        None => true,
    }
}

