        f.debug_struct("UnshieldedOffer")
            .field("inputs", &self.inputs)
            .field("outputs", &self.outputs)
            .field(
                "signatures",
                &format_args!("[{} signatures]", self.signatures.len()),
            )
            .finish()
    }
